#!/usr/bin/env python3
"""Generate docs/pumpfun/08-data-dictionary.md by introspecting one daily collector JSON and the published CSV files.
Keys are the tool's own (French); the description column is the author's. Run from the repository root."""
import json, csv, gzip, glob, os
S = 'data/pumpfun-16d'; OUT = 'docs/pumpfun/08-data-dictionary.md'
DESC = {
 'genere': 'timestamp of the tool run', 'fenetre': 'UTC window [start, end]', 'coupe': 'first minute with full data (diagnostic)', 'dureeSlot': 'mean slot duration (s) over the day',
 'fenetre3s': 'number of slots in the 3-second window used for the creator-sell test', 'couverture': 'coverage: minutes expected/read, minutes without source, duplicates lost, unreadable, canary per program',
 'couverture.canari': 'per program: controls run, errors, expected vs received transactions, worst ratio', 'lecture': 'what was read: files, lines, transactions, duplicates, bundles, accounts, largest hands',
 'prixSol': 'SOL price used for dollar conversions', 'prioLamports': 'median priority fee (lamports)', 'coutARSol': 'cost of a round trip in SOL (fees only)',
 'verifications': 'curve-formula checks: swaps, chained, formula OK, max relative deviation, buy-up / sell-down counts, off-chain', 'verificationsParFamille': 'the same per launch family',
 'fraisBps': '[fee in bps, swaps checked]', 'fraisCreateurBps': '[creator fee in bps, swaps checked]', 'parHeure': '24 rows: hour, tokens born, no-trade share, second-buyer share, replay buy 60 s / hold 60 s (r6060) and buy 20 s / hold 160 s (r20180): n, robust mean, mean, median',
 'verificationsLaunchLab': 'Raydium LaunchLab: swaps (echanges), chain checks, formula checks, fee checks, fee tiers in bps', 'sniper': 'replay at 2 s and 5 s entry: n, marginal mean / robust / median, net of a 0.1 SOL buy',
 'familles': 'per launch family (pf|SOL = SOL-quoted pump.fun tokens, the paper\'s universe; pf|SOL|mayhem; pf|autres cotations = other quote tokens; ll|… = LaunchLab)',
 'familles.X.tout': 'the whole day; "1re moitié" / "2de moitié" = first and second half of the day (out-of-sample test); choixMarcheAvant = the cell chosen on the first half and its result on the second',
 'tout.jetons': 'tokens born', 'tout.parHeure': 'tokens per hour', 'tout.secondAcheteur': 'share of tokens with a buy from outside the creator within 60 s', 'tout.secondAcheteurStrict': 'same, strict (bundle / sniper patterns excluded)',
 'tout.secondStrict001': 'strict and buy ≥ 0.01 SOL', 'tout.secondStrict005': 'strict and buy ≥ 0.05 SOL', 'tout.gradues': 'tokens that graduated', 'tout.echangesMed': 'median swaps per token', 'tout.venteTiers': 'share of tokens with at least one third-party sale',
 'tout.jouablesParHeure': 'tokens per hour still alive at E seconds (E = 10, 20, 30, 45, 60)', 'tout.fouleNonGradues': 'third-party positions on non-graduated tokens by entry age bucket: positions, SOL paid, strict P&L (stake-weighted), valued P&L, median strict, winners share, never-sold share',
 'tout.fouleGradues': 'same on graduated tokens', 'tout.foule': 'same on all tokens (dansGradues = share of positions on graduated tokens)', 'tout.temoinPositif': 'positive control: graduated tokens, median price multiple birth → end of curve (theory 14.7), median SOL in the curve at graduation',
 'tout.sansEchange': 'share of tokens with no swap', 'tout.mainCreateur': 'the creator\'s own trades: tokens, SOL paid, SOL received, P&L', 'tout.tiers': 'real third-party buys at entry E and exit H: n, mean, 95 % CI, robust mean, median, winners, median stake, graduated excluded, without dust',
 'tout.rejeu': 'exact-state replay of a small buy at E sold at H: n, per hour, graduated, marginal (mean, CI, robust, median), net of a 0.005 / 0.01 / 0.05 / 0.1 SOL buy, flow after the buy', 'tout.venteCreateur': 'creator sells ≤ 3 s after an outside buy vs matched control, two definitions (creator; creator + creation slot)',
}
L = ['# Data dictionary', '', '*Generated by `scripts/data_dictionary.py`. The daily JSON files are the unmodified output of the lab tool (`scripts/lab/solana-courbes.mjs`); their keys are in French, the tool\'s language, and are described here in English. Percentages are fractions (0.174 = 17.4 %); SOL amounts are in SOL.*', '']
day = sorted(glob.glob(os.path.join(S, '2026-10-*.json')))[1]
with open(day) as f: J = json.load(f)
def typ(v): return type(v).__name__ + (f'[{len(v)}]' if isinstance(v, (list, dict)) else '')
L += ['## `data/pumpfun-16d/<day>.json` (one per UTC day)', '', '| key | type | description |', '|---|---|---|']
for k, v in J.items():
    if k == 'familles': L.append(f'| `familles` | dict[{len(v)}] | {DESC["familles"]} |'); continue
    L.append(f'| `{k}` | {typ(v)} | {DESC.get(k, "")} |')
L += ['', '### `familles["pf|SOL"]["tout"]` (same keys for the other families and for the two half-days)', '', '| key | type | description |', '|---|---|---|']
for k, v in J['familles']['pf|SOL']['tout'].items(): L.append(f'| `{k}` | {typ(v)} | {DESC.get("tout."+k, "")} |')
L += ['', f'`familles["pf|SOL"]` also has: `1re moitié`, `2de moitié` (the two halves of the day, same keys as `tout`) and `choixMarcheAvant` ({DESC["familles.X.tout"].split(";")[-1].strip()}).', '']
L += ['## `data/pumpfun-16d/crowd_20-60s.csv.gz`', '', 'One row per position of the 20–60 s crowd on non-graduated SOL-quoted tokens (1,691,317 rows), no address.', '', '| column | description |', '|---|---|',
      '| `day` | UTC day of the token\'s birth |', '| `age_s` | seconds between the token\'s birth and the position\'s first buy |', '| `paid_sol` | SOL paid (all buys of the position) |', '| `strict_pnl` | SOL received ÷ SOL paid − 1, unsold tokens at zero |', '| `valued_pnl` | same, unsold tokens at the last curve price |', '| `never_sold` | 1 if no sale at all |', '| `closed` | 1 if the position was fully closed |', '']
L += ['## `data/pumpfun-16d/active_buyers_by_day_ids.csv.gz`', '', 'One row per (day, buyer): every address with at least one curve buy that day, as an integer id stable over the 16 days (2,172,420 rows, 1,129,662 ids).', '']
for name, path in [('`data/pumpfun-16d/aggregate-pumpfun.json`', 'the 16-day aggregate written by `aggregate.py` (fenetre, couverture, jetons, secondAcheteur…, foule2060 = the 20–60 s crowd, fouleTousAgesNonGradues, adresses = distinct / active per day / new per day / 7-day new / retention cohorts, parJour = one row per day, confiance = confidence intervals and tests)'), ('`data/pumpfun-16d/food-chain-published.json`', 'the food chain: addresses grouped by positions taken (segments, variant all / nongrad), script and occasional profiles'), ('`data/pumpfun-16d/users.json`', 'users and revenue per active buyer, day by day'), ('`results/robustness_2060.csv`', 'the robustness variants of the 20–60 s median, day by day (columns named in the header)'), ('`results/food_chain_recomputed.json`', 'the food chain recomputed by `scripts/food_chain.py` from the per-position files'), ('`results/numbers.csv`', 'the paper\'s numbers recomputed: id, claim, paper value, recomputed, status A/B/C, result')]:
    L.append(f'- {name} — {path}')
L.append('')
L += ['## Derived CSV files in `data/`', '']
for f in sorted(glob.glob('data/*.csv')):
    with open(f) as fh: hdr = next(csv.reader(fh))
    L.append(f'- `{f}`: ' + ', '.join(f'`{c}`' for c in hdr))
L += ['', '`data/bots-daily.csv` is the day-by-day table of the bot campaign (Fig. 2 and Fig. C1 of the paper): births per day of the two factory families, the bots\' net dollars, median pool life, share of the author\'s buys drained, events (in French, as logged).', '']
L += ['## `data/raw/`', '', 'Unedited API responses: DefiLlama `summary/fees/<protocol>` (`totalDataChart` = [timestamp, value] per day; `totalDataChartBreakdown` = per chain and product), CoinGecko `coins/<id>` and `market_chart` (`prices`, `market_caps` as [ms, value]), `coins/markets` (comparables), Binance `fapi/v1/fundingRate` and `futures/data/openInterestHist`, Hyperliquid `meta`, and the Solscan holder table read by hand on October 22, 2026 (`solscan_pump_holders_2026-10-22.md`).']
os.makedirs('docs/pumpfun', exist_ok=True)
with open(OUT, 'w') as f: f.write('\n'.join(L))
print('ok', OUT)
